"""Present exploratory historical tests without implying score calibration."""
from html import escape
from backtest_topics import evaluate


def backtest_page(data):
    assert data['folds'] == evaluate(), 'Regenerate topic-backtest.json after source changes'
    methods=[('past_all','מועדים קודמים'),('past_b','מועדי ב׳ קודמים'),
             ('current_a','הנושאים במועד א׳ הנוכחי'),('hybrid','שילוב שווה של שלוש השיטות')]
    body='''<p class="study-intro"><strong>זו בדיקה בדיעבד של נושאים רחבים, לא דיוק של תחזית השאלות ולא הסתברות לשאלה עתידית.</strong> היא ממחישה כמה מידע אפשר להפיק מהעבר ומה מגבלותיו.</p>
<h2>איך נערכה הבדיקה?</h2><p>בכל אחד משבעת זוגות א׳/ב׳ דירגנו תשע משפחות נושא ובדקנו כיסוי של חמש מהן במועד ב׳. ההיסטוריה כוללת רק שאלונים שקדמו למועד א׳ של אותו זוג; השיטה הנוכחית רואה גם את מועד א׳. מועד ב׳ הנבחן ומועדים מאוחרים לא שימשו לחישוב הדירוג באותו זוג.</p>
<p>כאשר יש תיקו בגבול חמשת המקומות, הכיסוי מחושב כממוצע על פני שבירת התיקו באקראי. לדוגמה, אם נותר מקום אחד בין ארבעה נושאים בשוויון, כל אחד מקבל משקל רבע. זהו ממוצע צפוי ולא בהכרח תוצאה של בחירה יחידה. הממוצע הכולל נותן משקל שווה לכל אחד משבעת המועדים, כולל 2022 בעל 12 שאלות הברירה.</p>
<div class="study-table"><table><thead><tr><th>שיטת דירוג</th><th>שיעור שאלות ב׳ מכוסה — ממוצע</th><th>שיעור נושאים בב׳ מכוסה — ממוצע</th></tr></thead><tbody>'''
    for key,label in methods:
        m=data['macro_means'][key]
        body+=f'<tr><td>{label}</td><td>{100*m["question_coverage"]:.1f}%</td><td>{100*m["topic_recall"]:.1f}%</td></tr>'
    body+='''<tr><td>בחירת חמש מתוך תשע באקראי — תוחלת</td><td>55.6%</td><td>55.6%</td></tr></tbody></table></div>
<h2>התוצאה בכל זוג</h2><p>הטבלה מציגה את השילוב השווה בין שלוש שיטות הדירוג. האחוז הוא חלק השאלות שהנושא הראשי שלהן נכלל בחמשת המקומות, כולל שקלול תיקו.</p><div class="study-table"><table><thead><tr><th>מועד א׳</th><th>מועד ב׳</th><th>מועדי ב׳ קודמים שהיו ידועים</th><th>כיסוי שאלות ב׳</th></tr></thead><tbody>'''
    for row in data['folds']:
        body+=f'<tr><td>{escape(row["a"])}</td><td>{escape(row["b"])}</td><td>{row["prior_b"]}</td><td>{100*row["metrics"]["hybrid"]["question_coverage"]:.1f}%</td></tr>'
    return body+'''</tbody></table></div><p>במועד הראשון לא היו כלל מועדים קודמים במאגר, ולכן דירוגי ההיסטוריה היו בתיקו מלא. בקיץ 2025 הכיסוי המשולב היה 40%, ובסמסטר ב׳ 2025 היה 80%. התנודות גדולות והמדגם קטן; אין מכך הוכחה שמודל אחד עדיף או שהשיעור יחזור.</p>
<h2>אותו נושא, פעולה אחרת</h2><ul><li>ב-2025 מועד א׳ שאל על יצירת חתימת RSA; מועד ב׳ נתן את אותו מודולוס ואותו מפתח פרטי אך שאל על שחזור ההודעה. <a href="solutions/Q105.html">Q105 — מועד א׳</a> · <a href="solutions/Q113.html">Q113 — מועד ב׳</a>.</li>
<li>בקיץ 2025 שאלת א׳ ביקשה הגדרת preimage, ושאלת ב׳ ביקשה second preimage. נוסח וכמה חלופות דומים, אך התשובה והתנאים שונים. <a href="solutions/Q130.html">Q130 — מועד א׳</a> · <a href="solutions/Q140.html">Q140 — מועד ב׳</a>.</li></ul>
<p>שאלות כלליות בנוסח ״איזו טענה נכונה?״ עשויות להיראות זהות אם משווים רק את השאלה בלי החלופות; כך גם שאלות בעלות חלופות דומות עשויות לבדוק תנאי אחר. לכן השוואה מילולית בלבד אינה מוכיחה זהות של דרישת הפתרון.</p>
<h2>דוגמה נוספת: אותו hash בפורמט שונה</h2><p>במועד א׳ קיץ 2022 נבחנה בשאלה פתוחה פונקציית hash שמחברת את ערכי אותיות a–z לפי a=0 ומחזירה סכום מודולו 26. שאלה 10 במועד א׳ אוקטובר 2026 השתמשה באותה בנייה בשאלת ברירה על התנגשויות. <a href="2022/File_1_689156_07102022_0.pdf#page=3">מקור 2022 — השאלה הפתוחה בעמוד 3</a> · <a href="solutions/Q182.html">שאלת הברירה באוקטובר 2026</a> · <a href="predictions.html#P51">תרגול דומה במודולוס שונה</a>.</p>
<p>זו דוגמה לחזרה על בנייה לאורך זמן, לא התאמת א׳→ב׳ באותו סמסטר ולא ראיה שהבנייה תופיע בבחינה הבאה. השאלה הפתוחה אינה נכנסת למנייני שאלות הברירה, לתמהיל הסימולציה או לשאלות התחזית. הקישור למסמך המקור פותח את השאלה הפתוחה לצורך אימות הראיה בלבד.</p>
<h2>מה לא נמדד</h2><p>השיטות והתיוג נבחרו בדיעבד לאחר שנראו הבחינות; חלוקת הנושאים מבוססת על הנושא הראשי, לא על תיוג ממצה של כל חלופה. השאלונים אינם בהכרח בלתי תלויים, והדירוגים לא הוקפאו לפני הבחינות. לא נבדקו 60 השאלות, הסימולציה של 10 שאלות, התאמת פעולות ברמת מיומנות, או דיוק ציוני 1–100. הבדיקה אינה מחליטה איזה תמהיל או ציון הוא הטוב ביותר לקראת הבחינה העתידית.</p>
<p><a href="data/topic-backtest.json">כל נתוני החישוב לפי זוג ושיטה (JSON)</a> · <a href="exam-covers.html">אימות הזוגות במסמכי המקור</a> · <a href="confidence.html">שיטת ציוני הביטחון</a></p>'''


def allocation_section(data):
    labels=[('history','ממוצע מועדי ב׳ קודמים'),('recent','מועד ב׳ האחרון בלבד'),
            ('current_a','מועד א׳ של אותו זוג'),('combined','ממוצע שווה: היסטוריית ב׳ ומועד א׳')]
    body='''<h2 id="allocation-backtest">בדיקה כרונולוגית של תמהיל עשר שאלות</h2>
<p>בדקנו שישה זוגות שבהם היה לפחות מועד ב׳ קודם ידוע; הזוג הראשון מ-2022 אינו נכלל בתוצאות כי לא היה לו מועד ב׳ קודם במאגר. בכל זוג חישבנו תמהיל לפי המידע שהיה קיים לפני ב׳: רק מועדי ב׳ שקדמו לא׳, ובשיטות המתאימות גם א׳ של אותו זוג. בכל מועד מנרמלים את מספר שאלות הברירה לעשר; בתמהיל מחלקים עשרה מקומות לפי השאריות הגדולות, ובתיקו לפי שם הנושא.</p>
<p>המדד הוא חפיפה במספרי השאלות לפי נושא ראשי: לכל נושא לוקחים את הקטן מבין מספר המקומות בתמהיל ומספר השאלות בב׳, מחברים ומחלקים בעשר. למשל, תמהיל עם שתי שאלות בנושא מסוים ובחינה עם אחת תורמים מקום אחד. זה <strong>אינו שיעור שאלות או מיומנויות שנוחשו</strong>: שאלות שונות לגמרי יכולות להיחשב באותו נושא.</p>
<div class="study-table"><table><thead><tr><th>כלל תמהיל</th><th>חפיפה ממוצעת בשישה זוגות</th></tr></thead><tbody>'''
    for name,label in labels:
        body+=f'<tr><td>{escape(label)}</td><td>{100*data["means"][name]:.1f}%</td></tr>'
    body+='''</tbody></table></div><div class="study-table"><table><thead><tr><th>מועד ב׳ שנבדק</th><th>ב׳ קודמים</th><th>ממוצע ב׳</th><th>ב׳ אחרון</th><th>א׳ באותו זוג</th><th>שילוב</th></tr></thead><tbody>'''
    for row in data['folds']:
        values=''.join(f'<td>{100*row["overlap"][key]:.1f}%</td>' for key,_ in labels)
        body+=f'<tr><td>{escape(row["b"])}</td><td>{len(row["training_b"])}</td>{values}</tr>'
    return body+'''</tbody></table></div><p>השילוב הגיע לממוצע מעט גבוה יותר במדגם הזה, אך היה נמוך יותר באחד מששת הזוגות, והתוצאה רגישה לשיטות ולשישה מועדים בלבד. החלוקה לנושאים וההשוואה נבחרו בדיעבד לאחר שראינו את הבחינות; זו אינה בדיקה פרוספקטיבית קפואה, אינה בודקת דיוק של 60 התחזיות או את הציונים שלהן, ואינה מוכיחה שהשילוב יצליח יותר בעתיד. לכן תמהיל הסימולציה לא שונה על סמך ההפרש הזה.</p><p><a href="data/allocation-backtest.json">נתוני התמהילים, מועדי האימון והחפיפה לכל זוג</a> · <a href="best-mock.html">התמהיל הנוכחי</a></p>'''


def skill_section(data):
    body='''<h2 id="skill-backtest">השוואת בונוס מועד א׳ במיפוי מיומנויות</h2><p>בדיקה חקרנית זו מדרגת בכל זוג עשר מיומנויות שונות מתוך מיומנויות 60 התחזיות הנוכחיות. חישוב הרכיבים משתמש רק במועדים עד א׳ ובזוגות ב׳ שהסתיימו לפניו; הבונוס בגרסה הראשונה מתבסס על א׳ של אותו זוג. בגרסה השנייה הבונוס מוסר ושאר המשקלים מוגדלים יחסית ל-100, עם אותו ניכוי הרחבה. הדירוג כאן אינו כופה את תמהיל הסימולציה.</p>
<p>מספר ההתאמות סופר מיומנות שנבחרה ושמופתה גם למקור בב׳. המיפוי ידני וחלקי ונוצר אחרי שראינו את הבחינות; גם 60 התרגילים והמיומנויות נבחרו בדיעבד. ייתכן שמיומנות שלא מופתה בכל זאת נבחנה, וששאלה אחת תתמוך בכמה מיומנויות. לכן זו אינה תחזית שהוקפאה מראש, לא אחוז פגיעה בשאלות, ולא בדיקת דיוק של הסימולציה או של ציוני הביטחון.</p><div class="study-table"><table><thead><tr><th>מועד ב׳</th><th>מיומנויות ממופות בב׳</th><th>התאמות בעשר עם בונוס</th><th>התאמות בעשר ללא בונוס</th></tr></thead><tbody>'''
    for row in data['folds']:
        body+=f'<tr><td>{escape(row["b"])}</td><td>{len(row["mapped_target_skills"])}</td><td>{row["bonus_hits"]}/10</td><td>{row["no_bonus_hits"]}/10</td></tr>'
    body+=f'</tbody></table></div><p>סך ההתאמות בשבעת הזוגות: {data["bonus_hits"]} עם הבונוס ו-{data["no_bonus_hits"]} בלעדיו. המדגם קטן, המיפוי חלקי ותלוי בחירות בדיעבד; הפער אינו מוכיח שאחת השיטות עדיפה על השנייה או מתאר סיכוי עתידי. התאמות במיומנויות אינן שוות למספר השאלות שנוחשו.</p>'
    return body+'''<p><a href="data/skill-backtest.json">הבחירות, המועדים ומיומנויות היעד שנמפו (JSON)</a> · <a href="sensitivity.html">בדיקת רגישות של הסימולציה בפועל</a></p>'''
